class ListNode {
  int val;
  ListNode next;

  ListNode(int x) {
    val = x;
  }
}

class Solution {
  public ListNode partition(ListNode head, int x) {
    ListNode lessDummy = new ListNode(0);
    ListNode greaterDummy = new ListNode(0);
    ListNode less = lessDummy, greater = greaterDummy;
    for (ListNode cur = head; cur != null; cur = cur.next) {
      if (cur.val < x) {
        less.next = cur;
        less = cur;
      } else {
        greater.next = cur;
        greater = cur;
      }
    }
    greater.next = null;
    less.next = greaterDummy.next;
    return lessDummy.next;
  }
}

impl Solution {
  pub fn partition(head: Option<Box<ListNode>>, x: i32) -> Option<Box<ListNode>> {
    let mut less_dummy = ListNode::new(0);
    let mut greater_dummy = ListNode::new(0);
    let mut less = &mut less_dummy;
    let mut greater = &mut greater_dummy;
    let mut cur = head;
    while let Some(mut node) = cur {
      cur = node.next.take();
      if node.val < x {
        less.next = Some(node);
        less = less.next.as_mut().unwrap();
      } else {
        greater.next = Some(node);
        greater = greater.next.as_mut().unwrap();
      }
    }
    less.next = greater_dummy.next;
    less_dummy.next
  }
}

const partition = (head: ListNode | null, x: number): ListNode | null => {
  const lessDummy = new ListNode(0);
  const greaterDummy = new ListNode(0);
  let less: ListNode = lessDummy;
  let greater: ListNode = greaterDummy;
  let cur = head;
  while (cur) {
    if (cur.val < x) {
      less.next = cur;
      less = cur;
    } else {
      greater.next = cur;
      greater = cur;
    }
    cur = cur.next;
  }
  greater.next = null;
  less.next = greaterDummy.next;
  return lessDummy.next;
};
